mapper.select:
SELECT id, operation_type as type, 'police_report' as entityType, report_id as entityId, field_name as fieldName, field_label as fieldLabel, old_value as oldValue, new_value as newValue, user_id as userId, user_name as userName, ip_address as ipAddress, user_agent as userAgent, description, operation_time as operationTime, UNIX_TIMESTAMP(operation_time) * 1000 as timestamp, ext_data FROM t_police_report_operation_log
AND report_id = #{query.entityId}
AND user_id = #{query.userId}
AND field_name = #{query.fieldName}
AND operation_type = #{query.operationType}
AND UNIX_TIMESTAMP(operation_time) * 1000 >= #{query.startTime}
AND UNIX_TIMESTAMP(operation_time) * 1000 <= #{query.endTime}
ORDER BY operation_time DESC

SELECT COUNT(1)
FROM t_police_report_operation_log


        AND report_id = #{query.entityId}


        AND user_id = #{query.userId}


        AND field_name = #{query.fieldName}


        AND operation_type = #{query.operationType}


        AND UNIX_TIMESTAMP(operation_time) * 1000 >= #{query.startTime}


        AND UNIX_TIMESTAMP(operation_time) * 1000 <= #{query.endTime}

SELECT *
FROM t_police_report_operation_log
WHERE report_id = #{reportId}
ORDER BY operation_time DESC

    LIMIT #{limit}

SELECT *
FROM t_police_report_operation_log
WHERE user_id = #{userId}
ORDER BY operation_time DESC

    LIMIT #{limit}

SELECT COUNT(1)
FROM t_police_report_operation_log
WHERE report_id = #{reportId}

SELECT * FROM t_police_report_operation_log WHERE report_id = #{reportId}
AND operation_time >= DATE_SUB(NOW(), INTERVAL #{hours} HOUR)
ORDER BY operation_time DESC
